    op.add_column('player_ratings', sa.Column('peak_rating', sa.Double(), server_default='0', nullable=False))
    # ### end Alembic commands ###

    op.execute("""
        UPDATE player_ratings pr
        SET peak_rating = GREATEST(pr.display_rating, sub.peak)
        FROM (
            SELECT user_id, game, playtype, ladder, MAX(player_display_after) AS peak
            FROM matches
            WHERE type = 'competitive' AND player_display_after IS NOT NULL
            GROUP BY user_id, game, playtype, ladder
        ) sub
        WHERE pr.user_id = sub.user_id
        AND pr.game = sub.game
        AND pr.playtype = sub.playtype
        AND pr.ladder = sub.ladder
    """)
    op.execute("UPDATE player_ratings SET peak_rating = display_rating WHERE peak_rating = 0")


